<script lang="ts">
  import { onMount } from "svelte";
  import CombatFleetPanel from "./CombatFleetPanel.svelte";
  import { checkPluginRun, createPilotReach, createPluginRunGrant, loadKnownAccounts, loadKnownCharacters, pluginPostJson, pluginGetJson, skipWhileBusy, startPluginRun, type GlobalWindowProps, type JsonValue, type PluginRunPolicy, type ServerBot, type Session } from "../../../web/src/plugin-api/index.ts";
  import { matchingSecurityProgress, securityHistoryRows, type SecurityHistoryRow } from "./progressView.ts";
  import { createTrainingAccountPass } from "../training/accountPass.ts";
  import { prepareHeldPilot } from "../heldPilot.ts";
  import type { FoundAgent } from "../shared/types.ts";
  let {sessions=[]}:GlobalWindowProps=$props();
  type Pilot={characterID:number;name:string;accountName:string;session:Session|null};
  let pilots=$state<Pilot[]>([]),roster=$state<Pilot[]>([]),account=$state(""),pilotID=$state(0),agentID=$state<number|null>(null),count=$state(1),agentMode=$state<"manual"|"auto">("manual"),maxJumps=$state(10),corporationID=$state(""),durationMinutes=$state(720),parkingMode=$state<"nearest"|"selected">("nearest"),parkingKind=$state<"station"|"structure">("station"),parkingDestinationID=$state<number|null>(null),parkingSystemID=$state<number|null>(null),query=$state(""),agents=$state<FoundAgent[]>([]),capped=$state(false),busy=$state(false),error=$state(""),rosterError=$state(""),bots=$state<ServerBot[]>([]);
  let summaries=$state<Record<string,Record<string,JsonValue>>>({});let refreshSequence=0;
  let history=$state<(SecurityHistoryRow & {pilotName:string})[]>([]);
  const key=(b:Pick<ServerBot,"botID"|"characterID">)=>JSON.stringify([b.characterID,b.botID]);
  function progress(b:ServerBot):Record<string,JsonValue>|null{const value=summaries[key(b)]??b.plugin?.readout;return value&&typeof value==="object"&&!Array.isArray(value)?value as Record<string,JsonValue>:null;}
  let reviewed=$state<{setup:JsonValue;policy:PluginRunPolicy;name:string;fingerprint:string;accountName:string;characterID:number}|null>(null);
  const selected=$derived(pilots.find(p=>p.characterID===pilotID)??null), fingerprint=$derived(JSON.stringify([agentMode,agentID,maxJumps,corporationID,durationMinutes,parkingMode,parkingKind,parkingDestinationID,parkingSystemID,count,pilotID,selected?.characterID]));
  const valid=$derived(reviewed!==null&&reviewed.fingerprint===fingerprint&&reviewed.accountName===selected?.accountName&&reviewed.characterID===selected?.characterID);
  const matching=$derived(agents.filter(a=>[a.name,a.stationName,a.solarSystemName,a.corporationName].some(s=>s?.toLowerCase().includes(query.trim().toLowerCase()))));
  const reach=createPilotReach({pass:createTrainingAccountPass(),held:()=>sessions,known:()=>[...roster.map(p=>({characterID:p.characterID,characterName:p.name,accountName:p.accountName})),...pilots.map(p=>({characterID:p.characterID,characterName:p.name,accountName:p.accountName})),...loadKnownCharacters()],accounts:()=>[...new Set([...roster.map(p=>p.accountName),...(account.trim()?[account.trim()]:[]),...loadKnownAccounts(),...sessions.map(s=>s.store.get().session.username).filter((v):v is string=>!!v)])]});
  $effect(()=>{const loaded=roster;const update=()=>{const live: Pilot[]=sessions.flatMap(session=>{const s=session.store.get(),online=s.station.online,name=s.session.username;return session.flow.sessionToken()&&s.session.phase==="logged-in"&&online&&name&&s.character.selectedCharacterID===online.characterID?[{session,characterID:online.characterID,name:online.characterName,accountName:name}]:[];});pilots=[...live,...loaded.filter(p=>!live.some(x=>x.characterID===p.characterID))];};update();const unsubs=sessions.flatMap(s=>[s.store.session.subscribe(update),s.store.character.subscribe(update),s.store.station.subscribe(update)]);return()=>unsubs.forEach(f=>f());});
  function owner(){const p=selected;if(!p)throw Error("Select a pilot from an authenticated account.");if(p.session){const s=p.session.store.get();if(!p.session.flow.sessionToken()||s.session.phase!=="logged-in"||s.character.selectedCharacterID!==p.characterID||s.station.online?.characterID!==p.characterID)throw Error("Pilot session changed. Review again.");}return p;}
  async function loadPilots(){const name=account.trim();if(!name||busy)return;busy=true;error="";reviewed=null;roster=roster.filter(p=>p.accountName.toLowerCase()!==name.toLowerCase());pilotID=0;try{const o=await reach.accountOptions(name);if(!o.token)throw Error("Account authentication is unavailable.");const response=await(o.fetch??globalThis.fetch)(`${o.baseUrl??""}/api/pilot-training/characters`,{headers:{authorization:`Bearer ${o.token}`},credentials:"omit"});const data=await response.json();if(!response.ok||data.ok===false||typeof data.account!=="string"||data.account.toLowerCase()!==name.toLowerCase()||account.trim()!==name||!Array.isArray(data.characters))throw Error("The account roster is unavailable or changed.");const rows:Pilot[]=data.characters.map((c:any)=>{if(!Number.isSafeInteger(c?.characterID)||c.characterID<=0||typeof c.name!=="string"||!c.name)throw Error("The account roster is malformed.");return {characterID:c.characterID,name:c.name,accountName:data.account,session:null};});if(new Set(rows.map(p=>p.characterID)).size!==rows.length)throw Error("The account roster contains duplicate pilots.");roster=[...roster.filter(p=>p.accountName.toLowerCase()!==name.toLowerCase()),...rows];pilotID=0;}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
  async function find(){busy=true;error="";try{const p=owner(),o=await reach.ownerOptions(p.characterID),response=await(o.fetch??globalThis.fetch)(`${o.baseUrl??""}/api/agents/find?kind=encounter&level=1&limit=5000`,{headers:o.token?{authorization:`Bearer ${o.token}`}:{},credentials:o.token?"omit":"same-origin"});const r=await response.json();if(!response.ok||r.ok===false||!Array.isArray(r.agents)||typeof r.capped!=="boolean")throw Error("Security agent directory is unreadable.");if(owner().characterID!==p.characterID)throw Error("Pilot changed.");agents=r.agents.filter((a:FoundAgent)=>a.agentID>0&&a.level===1&&a.divisionID===24&&a.agentTypeID===2&&a.stationID!==null);capped=r.capped;agentID=null;reviewed=null;}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
  async function refresh(){const seq=++refreshSequence;try{const r=await reach.readServerBots();if(seq!==refreshSequence)return;rosterError=r.allFailed?"Could not read Security runs.":r.missing.length?`Could not read runs for ${r.missing.join(", ")}.`:"";if(r.allFailed)return;
   const found=r.bots.filter(b=>b.kind==="plugin"&&b.plugin?.pluginID==="uoc"&&b.plugin.run==="coc-security");bots=found;
   const [observations,histories]=await Promise.all([Promise.allSettled(found.filter(b=>!!b.endedAt).map(async b=>{const options=await reach.ownerOptions(b.characterID);const body=await pluginGetJson("uoc",`/security/${b.characterID}/progress?runID=${encodeURIComponent(b.botID)}`,options);return {key:key(b),readout:matchingSecurityProgress(b,body)};})),Promise.allSettled(roster.map(async p=>{const options=await reach.accountOptions(p.accountName);const body=await pluginGetJson("uoc",`/security/${p.characterID}/history`,options);return securityHistoryRows(p.characterID,body).map(row=>({...row,pilotName:p.name}));}))]);
   if(seq!==refreshSequence)return;const next:Record<string,Record<string,JsonValue>>={};for(const item of observations)if(item.status==="fulfilled"&&item.value.readout)next[item.value.key]=item.value.readout;summaries=next;history=histories.flatMap(item=>item.status==="fulfilled"?item.value:[]).filter(row=>!found.some(b=>b.characterID===row.characterID&&b.botID===row.runID));
  }catch(e){if(seq===refreshSequence)rosterError=e instanceof Error?e.message:String(e);}}
  async function review(){busy=true;error="";reviewed=null;try{const p=owner(),original=fingerprint;if(![1,2].includes(count))throw Error("Select one or two missions.");let setup:JsonValue;if(agentMode==="manual"){if(!agents.some(a=>a.agentID===agentID))throw Error("Select a level 1 Security agent.");setup={agentID,missionCount:count} as JsonValue;}else{const corp=corporationID.trim()?Number(corporationID):null;if(!Number.isSafeInteger(maxJumps)||maxJumps<0||maxJumps>100||corp!==null&&(!Number.isSafeInteger(corp)||corp<=0))throw Error("Enter a valid corporation and maximum jumps.");setup={agent:{mode:"auto",maxJumps,corporationID:corp},missionCount:count} as JsonValue;}if(!Number.isSafeInteger(durationMinutes)||durationMinutes<4||durationMinutes>4320)throw Error("Choose a runtime between 4 and 4320 minutes.");if(parkingMode==="selected"){if(!Number.isSafeInteger(parkingDestinationID)||!parkingDestinationID||parkingDestinationID<=0||!Number.isSafeInteger(parkingSystemID)||!parkingSystemID||parkingSystemID<=0)throw Error("Enter the destination and solar system IDs.");setup={...(setup as Record<string,JsonValue>),parking:{mode:"selected",kind:parkingKind,destinationID:parkingDestinationID,systemID:parkingSystemID}};}const r=await checkPluginRun("uoc","coc-security",setup,await reach.ownerOptions(p.characterID));if(fingerprint!==original||owner().characterID!==p.characterID)throw Error("Setup changed. Review again.");reviewed={...r,fingerprint:original,accountName:p.accountName,characterID:p.characterID};}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
  async function start(){if(!reviewed||!valid)return;busy=true;error="";try{const p=owner(),approved=reviewed;if(p.session)await prepareHeldPilot(p.session,p.characterID);if(!valid||reviewed!==approved||owner().characterID!==p.characterID)throw Error("Setup changed. Review again.");const options=await reach.ownerOptions(p.characterID);if(!valid||reviewed!==approved||owner().characterID!==p.characterID)throw Error("Setup changed. Review again.");await startPluginRun(p.characterID,"uoc","coc-security",approved.setup,createPluginRunGrant(approved.policy,durationMinutes),options);reviewed=null;await refresh();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
  async function stop(bot:ServerBot){busy=true;error="";try{await pluginPostJson("uoc",`/runs/${encodeURIComponent(bot.botID)}/stop`,{},await reach.ownerOptions(bot.characterID));await refresh();}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
  onMount(()=>{const tick=skipWhileBusy(refresh);void tick();const timer=setInterval(()=>void tick(),5000);return()=>{clearInterval(timer);void reach.release();};});
</script>
<section aria-label="Hosted Security missions">
  <h3>Security missions · solo level 1</h3>
  <p>The server verifies the offered mission and may stop if it is unsupported. Drones are recalled and parking is confirmed before the run ends.</p>
  <div class="fields"><label>Security account <input bind:value={account} disabled={busy} placeholder="Account name" /></label><button type="button" onclick={loadPilots} disabled={busy||!account.trim()}>Load pilots</button><label>Pilot <select bind:value={pilotID} disabled={busy}><option value={0}>Select a pilot</option>{#each pilots as p (p.characterID)}<option value={p.characterID}>{p.name} · {p.accountName} ({p.characterID})</option>{/each}</select></label>
    <label>Agent selection <select bind:value={agentMode} disabled={busy}><option value="manual">Choose an agent</option><option value="auto">Automatic eligible agent</option></select></label><label>Missions <select bind:value={count} disabled={busy}><option value={1}>1</option><option value={2}>2</option></select></label>
    {#if agentMode==="manual"}<button type="button" onclick={find} disabled={busy||!selected}>Find level 1 Security agents</button>{/if}</div>
  {#if agentMode==="auto"}<label>Maximum jumps <input type="number" min="0" max="100" bind:value={maxJumps} disabled={busy}/></label><label>NPC corporation ID (optional) <input inputmode="numeric" bind:value={corporationID} disabled={busy}/></label><p>The nearest accessible level 1 Security agent will be selected after Start.</p>{/if}
  {#if agentMode==="manual"&&agents.length}<label>Search agent <input type="search" bind:value={query}/></label><label>Agent <select bind:value={agentID} disabled={busy}><option value={null}>Select an agent</option>{#each matching as a (a.agentID)}<option value={a.agentID}>{a.name} · {a.stationName??"Station unavailable"} · {a.corporationName??""}</option>{/each}</select></label>{/if}
  {#if capped}<p>Only part of the agent directory was returned.</p>{/if}
  <label>Runtime limit (minutes) <input type="number" min="4" max="4320" step="1" bind:value={durationMinutes} disabled={busy}/></label>
  <label>Parking <select bind:value={parkingMode} disabled={busy}><option value="nearest">Nearest accessible dock at stop</option><option value="selected">Selected destination</option></select></label>{#if parkingMode==="selected"}<label>Destination type <select bind:value={parkingKind} disabled={busy}><option value="station">NPC station</option><option value="structure">Accessible structure</option></select></label><label>Destination ID <input type="number" min="1" bind:value={parkingDestinationID} disabled={busy}/></label><label>Solar system ID <input type="number" min="1" bind:value={parkingSystemID} disabled={busy}/></label>{/if}
  <button type="button" onclick={review} disabled={busy||!selected||(agentMode==="manual"&&!agentID)}>Review run</button>
  {#if error}<p role="alert">{error}</p>{/if}
  {#if reviewed&&valid}<div aria-label="Security run review"><h4>Review {reviewed.name}</h4><p>Pilot: {selected?.name}; missions: {count}; runtime limit: {durationMinutes} minutes; parking: {parkingMode==="nearest"?"nearest accessible dock":`selected ${parkingKind} ${parkingDestinationID} in system ${parkingSystemID}`}. {agentMode==="auto"?`Automatic eligible agent within ${maxJumps} jumps.`:"Selected Security agent."} Starting hands control to the server.</p><p>Risks: {reviewed.policy.riskClasses.join(", ")}; restart safe: {reviewed.policy.restartSafe?"yes":"no"}.</p><button type="button" onclick={start} disabled={busy}>Approve and start</button></div>{/if}
  <h4>Security runs</h4><button type="button" onclick={refresh} disabled={busy}>Refresh runs</button>{#if rosterError}<p role="alert">{rosterError}</p>{/if}
  {#if !bots.length&&!history.length&&!rosterError}<p>No Security runs found.</p>{/if}
  {#each bots as bot (bot.botID)}{@const readout=progress(bot)}<div aria-label="Security run" data-bot-id={bot.botID}><p>{bot.characterName??"Pilot"} · {bot.phase??bot.status}{bot.endedAt?" · ended":""}</p>{#if bot.why}<p>{bot.why}</p>{/if}{#if typeof readout?.completedCount==="number"}<p>Confirmed missions: {readout.completedCount}</p>{/if}{#if readout}<details><summary>Progress and receipts</summary><pre>{JSON.stringify(readout,null,2)}</pre></details>{/if}{#if !bot.endedAt}<button type="button" onclick={()=>stop(bot)} disabled={busy}>Stop run</button>{/if}</div>{/each}
  {#each history as row (`${row.characterID}:${row.runID}`)}<div aria-label="Security mission journal" data-bot-id={row.runID}><p>{row.pilotName} · Mission journal: {row.phase}</p><p>Confirmed missions: {row.completedCount}</p><p>Parking status unavailable from this journal.</p><details><summary>Latest mission receipt</summary><pre>{JSON.stringify(row.latestReceipt,null,2)}</pre></details></div>{/each}
</section>
<CombatFleetPanel {sessions} />
<style>.fields{display:flex;flex-wrap:wrap;align-items:end;gap:.75rem;margin-block:.75rem}label{display:grid;gap:.25rem;margin-block:.5rem}</style>
